    {   /* [2026-07-27] DISPTAB-WR : qui remplit la table de dispatch ? */
        static int _dt = -1; static unsigned _dtn = 0;
        if (_dt &lt; 0) _dt = calypso_gate("CALYPSO_DISPTAB", 0);
        if (_dt && addr &gt;= 0x4380 && addr &lt;= 0x43cf && _dtn &lt; 60) {
