            (unsigned)(a & 0xFFFF),
            !!(s-&gt;st0 & (1 &lt;&lt; 13)), s-&gt;insn_count);  /* TC = ST0 bit 13 per SPRU131G */
    }
    else if (pc == 0xfbf3 && g_fbdb_probe_count_fbf3 &lt; g_fbdb_probe_log_cap) {
        g_fbdb_probe_count_fbf3++;
