@pytest.mark.runtime_irda
def test_irda_pty_exists():
    """Un PTY IrDA est disponible (symlink ou /dev/pts/3 par fallback)."""
    ok, path = _pty_exists()
    assert ok, f"aucun PTY IrDA trouvé (cherché : {IRDA_PTY}, /dev/pts/3)"
    print(f"\n[irda] pty path = {path}")


@pytest.mark.runtime_irda
