                                "crc": split["original_crc"],
                                "addr": split["original_addr"],
                                "remaining": len(split["chunks"]),
                            }

                            print(
                                f"  [memwrite split] "
                                f"addr=0x{pending_reply['addr']:08x} "
                                f"total={pending_reply['nbytes']} "
                                f"chunks={pending_reply['remaining']}",
                                flush=True,
