                            for idx, sub in enumerate(split["chunks"], start=1):
                                frame = sercomm_wrap(DLCI_TX, sub)
                                print(
                                    f"  [-&gt;PTY sub {idx}/{len(split['chunks'])}] "
                                    f"{hexdump(frame)}",
                                    flush=True,
